def tr(text, lang):
    """A story or rule text in the chosen language (English is the source)."""
    if lang == "pt":
        return STORY_PT.get(text, text)
    return text


def ui(key, lang, **values):
    """A screen text in the chosen language, with {placeholders} filled in."""
    text = UI_TEXT[key]["pt" if lang == "pt" else "en"]
    return text.format(**values) if values else text

